import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { getMeetings, updateMeetingStatus } from '../../api';
import './Dashboard.css';

function HodDashboard({ user }) {
  const [meetings, setMeetings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [msg, setMsg] = useState('');

  useEffect(() => { load(); }, []);

  const load = async () => {
    try { 
      const r = await getMeetings(); 
      setMeetings(r.data); 
    } catch (e) { 
      console.error(e); 
    } finally { 
      setLoading(false); 
    }
  };

  const flash = (m) => { setMsg(m); setTimeout(() => setMsg(''), 3000); };

  const handleStatus = async (id, status) => {
    try { 
      await updateMeetingStatus(id, status); 
      flash(`✅ Meeting marked as ${status}`); 
      load(); 
    } catch (e) { 
      flash('❌ Failed'); 
    }
  };

  const today = new Date().toDateString();
  const todayMeetings = meetings.filter(m => new Date(m.date).toDateString() === today);
  const upcoming = meetings.filter(m => m.status === 'scheduled' && new Date(m.date) >= new Date());
  const completed = meetings.filter(m => m.status === 'completed');

  if (loading) return (
    <div className="flex-center" style={{ height: '100vh', flexDirection: 'column' }}>
      <div className="spinner"></div>
      <p style={{ marginTop: '1rem', color: '#64748b' }}>Loading SMVIT Dashboard...</p>
    </div>
  );

  return (
    <div className="dashboard-outer-wrapper">
      {/* Institutional Header with Lore Background */}
      <header className="inst-header">
        <div className="inst-container">
          <div className="inst-branding">
            <h2 className="inst-short">SMVIT</h2>
            <h1 className="inst-full">SIR M. VISVESVARAYA INSTITUTE OF TECHNOLOGY</h1>
            <p className="inst-creds">
              Affiliated to VTU, Belagavi | Approved by AICTE, New Delhi / Govt. of Karnataka | Accredited by NAAC
            </p>
          </div>

          <nav className="header-nav">
            <div className="nav-links">
              <Link to="/hod/dashboard" className="nav-item active">Dashboard</Link>
              <Link to="/hod/schedule" className="nav-item">Schedule Meeting</Link>
            </div>
            <button className="logout-btn" onClick={() => {/* Logout Logic */}}>
              Logout
            </button>
          </nav>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="dashboard-content">
        <div className="dashboard-header-flex">
          <div>
            <h2 className="page-title text-green">HOD Dashboard</h2>
            <p className="welcome-text">Welcome back, <span className="user-highlight">{user.name}</span></p>
          </div>
          <Link to="/hod/schedule">
            <button className="btn-teal-modern shadow-sm">+ Add Availability</button>
          </Link>
        </div>

        {msg && (
          <div className={`alert-floating ${msg.includes('❌') ? 'alert-error' : 'alert-success'}`}>
            {msg}
          </div>
        )}

        {/* Statistics Grid */}
        <div className="stat-grid-modern">
          <div className="stat-card-modern border-green">
            <div className="stat-info">
              <span className="stat-label">Today's Meetings</span>
              <div className="stat-num">{todayMeetings.length}</div>
            </div>
            <span className="stat-icon-bg">📅</span>
          </div>
          <div className="stat-card-modern border-blue">
            <div className="stat-info">
              <span className="stat-label">Upcoming</span>
              <div className="stat-num text-blue">{upcoming.length}</div>
            </div>
            <span className="stat-icon-bg">⏳</span>
          </div>
          <div className="stat-card-modern border-gray">
            <div className="stat-info">
              <span className="stat-label">Completed</span>
              <div className="stat-num text-gray">{completed.length}</div>
            </div>
            <span className="stat-icon-bg">✅</span>
          </div>
        </div>

        {/* Meeting List Table */}
        <div className="card-modern shadow-sm">
          <div className="card-header-modern">
            <h3>Meeting Schedule</h3>
          </div>

          <div className="table-wrapper">
            {meetings.length === 0 ? (
              <div className="empty-placeholder">
                <p>No meetings found in the records.</p>
              </div>
            ) : (
              <table className="modern-table">
                <thead>
                  <tr>
                    <th>Staff / Participant</th>
                    <th>Date & Time</th>
                    <th>Agenda</th>
                    <th>Status</th>
                    <th className="text-center">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {meetings.map(m => (
                    <tr key={m._id}>
                      <td className="font-semibold">
                        {m.scheduledBy?.name === user.name 
                          ? (m.attendees?.map(a => a.user?.name).join(', ') || '—') 
                          : m.scheduledBy?.name}
                      </td>
                      <td>
                        <div className="datetime-cell">
                          <span className="date-text">{new Date(m.date).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })}</span>
                          <span className="time-text">{m.time}</span>
                        </div>
                      </td>
                      <td className="agenda-text">{m.agenda || m.title}</td>
                      <td>
                        <span className={`status-pill pill-${m.status}`}>{m.status}</span>
                      </td>
                      <td>
                        <div className="action-cell">
                          {m.status === 'scheduled' && m.scheduledBy?._id === user.id && (
                            <button className="btn-table-success" onClick={() => handleStatus(m._id, 'completed')}>Done</button>
                          )}
                          {m.status === 'completed' && <span className="check-mark">✓ Done</span>}
                          {m.meetingLink && m.status === 'scheduled' && (
                            <a href={m.meetingLink} target="_blank" rel="noreferrer">
                              <button className="btn-table-primary">Join</button>
                            </a>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}

export default HodDashboard;
